def infer_format(conv):
    """Infer compression format from conversation metadata."""
    # Check file extensions or metadata
    filename = conv.get('compressed_file', '')
    if 'v4z' in filename:
        return 'slim_v4z'
    elif 'fsl' in filename:
        return 'slim_fsl'
    elif 'ztpcf' in filename:
        return 'slim_ztpcf'
    else:
        return 'slim_only'

