function generateSite(template, config) {
  const baseCode = loadTemplate(template);
  const compiled = baseCode
    .replace('{{LOCATIONS}}', JSON.stringify(config.locations))
    .replace('{{BUSINESS_NAME}}', config.business.name)
    .replace('{{PRIMARY_COLOR}}', config.business.primaryColor);

  writeFile(`./sites/${config.business.id}/app.js`, compiled);
}

