// Core email message in MCP format
interface PraxMessage {
  id: string;                    // UUID
  mcp_version: "1.0";
  type: "email" | "internal" | "notification";

  // Headers (MIME-compatible)
  headers: {
    from: string;
    to: string```;
    cc?: string```;
    bcc?: string```;
    subject: string;
    date: string;               // ISO 8601
    message_id: string;         // RFC 5322
    in_reply_to?: string;
    references?: string```;
  };

  // Body
  body: {
    text?: string;              // Plain text
    html?: string;              // HTML version
    attachments?: Attachment```;
  };

  // AI-generated metadata
  ai_metadata: {
    summary?: string;           // 1-2 sentence summary
    intent?: string;            // "request", "info", "action", "social"
    priority?: number;          // 0-100
    sentiment?: number;         // -1 to 1
    categories?: string```;      // Auto-detected categories
    entities?: Entity```;        // People, orgs, dates extracted
    suggested_response?: string;
    thread_summary?: string;    // For long threads
  };

  // Processing state
  state: {
    status: "received" | "processing" | "ready" | "archived";
    processed_at?: string;
    processed_by?: string;      // Agent ID
    checkpoint_id?: string;     // For recovery
  };
}

interface Attachment {
  filename: string;
  mime_type: string;
  size_bytes: number;
  content_id?: string;
  storage_uri: string;          // Local or cloud storage
}

interface Entity {
  type: "person" | "org" | "date" | "money" | "location";
  value: string;
  confidence: number;
}

