/**
 * Wraps async functions with error handling and user feedback
 */
async function withErrorHandling(fn, errorMessage = 'An error occurred') {
  try {
    return await fn();
  } catch (error) {
    console.error('[Error]:', error);
    if (window.toast) {
      window.toast.error(`${errorMessage}: ${error.message}`);
    }
    return { success: false, error: error.message };
  }
}

/**
 * Wraps async functions with loading state
 */
async function withLoading(fn, loadingEl) {
  const isButton = loadingEl instanceof HTMLButtonElement;
  const originalText = isButton ? loadingEl.textContent : null;

  try {
    if (isButton) {
      loadingEl.disabled = true;
      loadingEl.textContent = 'Loading...';
    } else if (loadingEl) {
      loadingEl.classList.add('loading');
    }

    return await fn();
  } finally {
    if (isButton) {
      loadingEl.disabled = false;
      loadingEl.textContent = originalText;
    } else if (loadingEl) {
      loadingEl.classList.remove('loading');
    }
  }
}

window.withErrorHandling = withErrorHandling;
window.withLoading = withLoading;

