  railway: {
    login: (token) => ipcRenderer.invoke('railway:login', token),
    signup: (username) => ipcRenderer.invoke('railway:signup', username),
    logout: () => ipcRenderer.invoke('railway:logout'),
    isLoggedIn: () => ipcRenderer.invoke('railway:isLoggedIn'),
    getInbox: () => ipcRenderer.invoke('railway:getInbox'),
    acceptTransfer: (transferId) => ipcRenderer.invoke('railway:acceptTransfer', transferId),
    getWallet: () => ipcRenderer.invoke('railway:getWallet'),
    sendStone: (stoneId, toUsername) => ipcRenderer.invoke('railway:sendStone', stoneId, toUsername),
    getConversations: () => ipcRenderer.invoke('railway:getConversations'),
    createConversation: (botType) => ipcRenderer.invoke('railway:createConversation', botType),
    getConversation: (conversationId) => ipcRenderer.invoke('railway:getConversation', conversationId),
    sendChatMessage: (conversationId, content, provider, botType) =>
      ipcRenderer.invoke('railway:sendChatMessage', conversationId, content, provider, botType),
    createCollabSession: (mode) => ipcRenderer.invoke('railway:createCollabSession', mode),
    joinCollabSession: (inviteCode) => ipcRenderer.invoke('railway:joinCollabSession', inviteCode),
    getCollabSession: (sessionId) => ipcRenderer.invoke('railway:getCollabSession', sessionId),
    listCollabSessions: () => ipcRenderer.invoke('railway:listCollabSessions'),
  },

  // Railway WebSocket events (one-way from main -> renderer)
  onRailwayEvent: (channel, callback) => {
    const validChannels = [
      'railway:transfer_received',
      'railway:transfer_sent',
      'railway:chat_response',
      'railway:collab_event',
      'railway:connected',
      'railway:disconnected'
    ];
    if (validChannels.includes(channel)) {
      ipcRenderer.on(channel, (event, ...args) => callback(...args));
    }
  },
  removeRailwayListener: (channel, callback) => {
    ipcRenderer.removeListener(channel, callback);
  }
});

