def verify_identity(stored_context, current_context) -> IdentityResult:
    scores = {
        "device": match_device(stored, current),      # 0-1
        "location": match_location(stored, current),  # 0-1
        "biometric": match_biometric(stored, current),# 0-1
        "behavior": match_behavior(stored, current),  # 0-1
    }

    weighted_score = sum(scores[k] * weights[k] for k in scores)

    if weighted_score >= 0.8:
        return IdentityResult.VERIFIED
    elif weighted_score >= 0.6:
        return IdentityResult.STEP_UP_REQUIRED  # Additional verification
    else:
        return IdentityResult.DENIED

