def compute_border_hash(stone):
    canonical = {
        "author": stone["border"]["author"],
        "created": stone["border"]["created"],
        "glow": stone["border"]["glow"],
        "chain": stone["border"]["chain"],
        "type": stone["type"],
        "wormholes": stone["wormholes"],
        "layers": {k: v["content"] for k, v in stone["layers"].items()}
    }
    return sha256(json.dumps(canonical, sort_keys=True))[:16]

